update pages set contenu = '{"sections":[{"type":"heros","h1":"Maintenance dans l''industrie chimique","mecanisme":"Le document avant l''outil. Permis de travail, consignations, contrôles d''atmosphère, modes opératoires : nos techniciens arrivent formés à ce cadre, et le respectent sans exception au motif de l''urgence.","cta":"Étudier la maintenance de mon site chimique","telephone":"04 78 33 72 05","phraseDelai":"Nous vous rappelons dans l''heure, du lundi au vendredi de 8h00 à 18h30. Astreinte 24/24 et 7/7 en option, aux mêmes exigences documentaires."},{"type":"chiffres","chiffres":[{"valeur":"10 %","libelle":"des candidats retenus, entretien technique et comportemental, résultats partagés"},{"valeur":"+ 120","libelle":"clients industriels, dont plus de 80 réguliers"},{"valeur":"4","libelle":"agences, Lyon (siège), Montréal, Dubaï, Madrid, astreinte 24/24 et 7/7"}]},{"type":"probleme","punchline":"Sur un site classé, un prestataire qui improvise ne vous coûte pas du temps. Il vous coûte un incident.","puces":[{"accroche":"L''intervenant qui découvre les règles ATEX chez vous est un danger.","texte":"Le choix d''un outil ou d''une lampe n''y est jamais anodin."},{"accroche":"Une unité qui tourne 24 heures sur 24 ne s''interrompt pas pour une visite.","texte":"L''entretien se place aux fenêtres programmées, le reste se fait en marche, dans les règles."},{"accroche":"Donneur d''ordre et entreprise extérieure engagent leur responsabilité ensemble.","texte":"Le choix d''un prestataire est une décision de sécurité avant d''être une décision d''achat."},{"accroche":"Sans permis, rien ne commence.","texte":"Permis de feu, permis de pénétrer, consignation des énergies : le circuit se respecte, quel que soit le retard annoncé."},{"accroche":"La culture sécurité ne s''improvise pas.","texte":"Et le marché local de l''emploi technique ne la fournit pas toute faite."}]},{"type":"offre","lignes":[{"prestation":"**Formations réglementaires vérifiées avant la mission**, attestations fournies à votre responsable HSE.","benefice":"Aucun intervenant n''entre sur le site sans que son dossier soit complet."},{"prestation":"**Respect strict de vos circuits de permis** : demande, validation, affichage, clôture.","benefice":"Vos équipes HSE ne passent pas leur journée à rattraper un prestataire."},{"prestation":"**Travail en zone ATEX** : habilitations, matériel certifié, modes opératoires adaptés, contrôles d''atmosphère.","benefice":"Les opérations en zone se préparent au lieu de se négocier au pied de l''unité."},{"prestation":"**Machines tournantes** : pompes de procédé, agitateurs, compresseurs, ventilateurs. Alignement, garnitures, roulements, équilibrage, analyse vibratoire.","benefice":"La mécanique qui tient vos unités est suivie par la mesure, pas par l''oreille."},{"prestation":"**Vannes, robinetterie et instrumentation** : actionneurs, sécurités mécaniques, boucles de régulation, étalonnages selon vos référentiels.","benefice":"La dérive de procédé se traite avant qu''elle ne devienne un écart qualité."},{"prestation":"**Tuyauteries et capacités** avec notre expertise en [tuyauterie industrielle](/expertises/tuyauterie/), en lien avec vos exigences d''inspection.","benefice":"Les travaux sur lignes suivent les modes opératoires attendus par votre service inspection."},{"prestation":"**Préparation d''arrêt d''unité** : équipe dimensionnée, qualifications vérifiées, tâches gammées, pièces anticipées.","benefice":"La fenêtre courte est tenue, et l''unité est rendue à la date promise."},{"prestation":"Exigence du site","benefice":"Réponse Migen"},{"prestation":"Formations réglementaires","benefice":"Vérifiées avant la mission, attestations fournies"},{"prestation":"Permis de travail","benefice":"Respect strict de vos circuits, aucun geste sans document"},{"prestation":"Zones ATEX","benefice":"Matériel aux normes, habilitations à jour, comportements maîtrisés"},{"prestation":"Consignations","benefice":"Procédures suivies, contrôles croisés acceptés"},{"prestation":"Traçabilité","benefice":"Comptes rendus au format de votre GMAO, disponibles à l''audit"},{"prestation":"Astreinte","benefice":"24/24 et 7/7 en option, mêmes règles la nuit que le jour"}],"prose":[{"texte":"Pour les modifications, notre [bureau d''études](/offres/bureau-etudes/) prépare des dossiers techniques au niveau attendu par vos études de dangers et votre gestion des modifications."}]},{"type":"deroule","etapes":[{"titre":"Cadrage sécurité","texte":"plan de prévention, analyse des risques liés aux agents chimiques, permis nécessaires, formations et qualifications exigées par le site. Vérifié avec votre responsable HSE avant le premier jour."},{"titre":"Vérification des dossiers","texte":"habilitations, attestations, aptitudes. Le technicien se présente avec un dossier complet, pas avec une promesse de régularisation."},{"titre":"Intervention sous permis","texte":"mode opératoire respecté, consignations réalisées, contrôles d''atmosphère quand ils s''imposent. Le document accompagne le geste."},{"titre":"Traçabilité","texte":"compte rendu détaillé, pièces remplacées, contrôles réalisés, écarts signalés. Votre GMAO et vos audits y trouvent l''information sans reconstitution."},{"titre":"Préparation des fenêtres de travaux","texte":"arrêts d''unité gammés, pièces anticipées, coactivité organisée."},{"titre":"Retour d''expérience","texte":"analyse des dysfonctionnements récurrents, propositions d''amélioration, relecture des événements marquants."}]},{"type":"garanties","puces":[{"accroche":"Aucun geste sans document","texte":"permis, consignation, mode opératoire. Cette règle ne cède pas devant l''urgence, et c''est ce que vous achetez en nous choisissant."},{"accroche":"Des dossiers complets avant l''accès","texte":"formations réglementaires, habilitations, aptitudes vérifiées. Les attestations sont remises à votre responsable sécurité, systématiquement."},{"accroche":"L''acceptation pleine de vos contrôles","texte":"contrôles croisés, points d''arrêt, surveillance par vos équipes. Nous ne discutons jamais un contrôle qui protège votre site."}]},{"type":"cta","question":"Besoin d''un prestataire dont le dossier sécurité est complet avant l''entrée sur site ?","bouton":"Étudier la maintenance de mon site chimique","rappel":"Ou appelez le 04 78 33 72 05, du lundi au vendredi de 8h00 à 18h30. Rappel dans l''heure."},{"type":"preuves","preuves":[{"titre":"Électromécanicien habilité risque chimique RC1, mobilisé 6 mois sur la remise en état d''un site de traitement des eaux industrielles","texte":"depuis février 2026","lienLibelle":"Étude de cas SUEZ : remise en état d''un site","lienHref":"/preuves/suez-remise-en-etat/"},{"titre":"Automaticien SIEMENS affecté au démarrage d''une ligne de production neuve, matériaux","texte":"près de Lyon","lienLibelle":"Étude de cas MERSEN : nouvelles lignes","lienHref":"/preuves/mersen/"},{"titre":"Maintenance préventive et curative d''une fonderie et d''un usinage, 7 jours sur 7","texte":"environnement thermique sévère, depuis octobre 2023","lienLibelle":"Étude de cas STELLANTIS : fonderie de Sept-Fons","lienHref":"/preuves/stellantis-fonderie-sept-fons/"},{"titre":"Trois techniciens en renfort sur la maintenance préventive d''une centrale photovoltaïque, énergie","texte":"septembre à novembre 2024","lienLibelle":"Étude de cas EIFFAGE : partenariat","lienHref":"/preuves/eiffage/"},{"titre":"Deux techniciens en 3x8 sur des lignes de process sous contrainte d''hygiène et de traçabilité","texte":"site de Steenvoorde","lienLibelle":"Étude de cas DANONE : lignes de production","lienHref":"/preuves/danone-lignes-de-production/"}]},{"type":"objections","questions":[{"question":"Vos techniciens sont-ils formés aux risques chimiques ?","reponse":"Oui. Les formations réglementaires attendues par les sites de la branche font partie de notre socle, et les formations spécifiques à votre établissement se réalisent avant la mission. Les attestations sont fournies à votre responsable sécurité, systématiquement."},{"question":"Pouvez-vous travailler en zone ATEX ?","reponse":"Oui, avec les habilitations, le matériel certifié et les modes opératoires adaptés. Les opérations en zone se préparent avec vos équipes, permis et contrôles d''atmosphère compris, sans exception au motif de l''urgence."},{"question":"Comment gérez-vous les permis de travail ?","reponse":"En suivant vos circuits : demande, validation, affichage, clôture. Nos techniciens connaissent la logique des permis de feu et de pénétrer. Rien ne commence avant le document."},{"question":"Intervenez-vous pendant les arrêts d''unité ?","reponse":"Oui, c''est un moment clé : forte densité de travaux, coactivité, fenêtre courte. Nous préparons ces arrêts avec vous, équipe dimensionnée, qualifications vérifiées, tâches gammées, pièces anticipées, pour rendre l''unité à la date promise."},{"question":"Que se passe-t-il en cas de panne la nuit sur un procédé continu ?","reponse":"L''astreinte 24/24 et 7/7 prend l''urgence en charge et mobilise un salarié depuis le hub de techniciens le plus proche, avec les mêmes exigences documentaires que le jour."},{"question":"Travaillez-vous pour la chimie fine comme pour la grande chimie ?","reponse":"Oui : unité continue, atelier batch, façonnier, laboratoire industriel. Les règles changent d''échelle, la culture reste la même. Notre expérience de la [pharmaceutique](/secteurs/pharmaceutique/) et de l''[agroalimentaire](/secteurs/agroalimentaire/) complète celle de la chimie."}]},{"type":"ctaFinal","question":"Besoin de préparer un arrêt d''unité avec une équipe qualifiée d''avance ?","bouton":"Parler à un chargé d''affaires","rappel":"ou appelez le 04 78 33 72 05, rappel dans l''heure aux horaires ouvrés."}]}'::jsonb where path = '/secteurs/chimie/';
